EMBEDDED_IMAGE_SOURCE_PATTERN = re.compile(
    r"<img\b[^>]{0,4096}\bsrc\s*=\s*(['\"])data:image/",
    flags=re.IGNORECASE,
)


def _requires_huge_html_parser(source: str) -> bool:
    """Permit large attributes only for an actual embedded image source."""

    return EMBEDDED_IMAGE_SOURCE_PATTERN.search(source) is not None


