def _normalize_scientific_prime_marks(value: str) -> str:
    """Canonicalize legacy 3/5-prime glyphs in nucleotide notation."""

    paired_quote_positions: set[int] = set()
    open_quotes: list[int] = []
    for index, character in enumerate(value):
        if character == "‘":
            open_quotes.append(index)
        elif character == "’" and open_quotes:
            paired_quote_positions.update((open_quotes.pop(), index))

    def replacement(match: re.Match[str]) -> str:
        # A right typographic quote can immediately follow a styled identifier,
        # for example ``‘Duplex 1: <em>F1</em>’``. Plain rendering sees the
        # complete quoted phrase while rich rendering visits the closing mark in
        # a separate tail node. Preserve balanced quotation marks so neither
        # representation misclassifies the closing quote as a nucleotide prime.
        return match.group(0) if match.start() in paired_quote_positions else "′"

    value = re.sub(
        r"(?<=\d)[‘’´ʹ](?=[A-Z/\-‐‑–—−·→←↔\s,;:.)]|$)",
        replacement,
        value,
    )
    value = re.sub(
        r"(?<=·N)[‘’´ʹ](?=[\s=:,;.)]|$)",
        replacement,
        value,
    )
    return re.sub(
        r"(?<=N)[‘’´ʹ](?=[ACGT:]|$)",
        replacement,
        value,
    )


def _normalize_scientific_caret(value: str) -> str:
    """Canonicalize an exact publisher exponent-caret encoding artifact."""

    return re.sub(r"(?<=\d)\u2041(?=\()", "^", value)


def _normalize_scientific_prime_marks_in_markup(value: str) -> str:
    """Canonicalize visible primes without treating balanced quotes as primes."""

    visible_positions: list[int] = []
    inside_tag = False
    for index, character in enumerate(value):
        if character == "<":
            inside_tag = True
        elif character == ">" and inside_tag:
            inside_tag = False
        elif not inside_tag:
            visible_positions.append(index)

    paired_quote_positions: set[int] = set()
    open_quotes: list[int] = []
    for index in visible_positions:
        character = value[index]
        if character == "‘":
            open_quotes.append(index)
        elif character == "’" and open_quotes:
            paired_quote_positions.update((open_quotes.pop(), index))

    allowed_following = set("ABCDEFGHIJKLMNOPQRSTUVWXYZ/-‐‑–—−·→←↔ =,;:.)\t\r\n")
    characters = list(value)
    for visible_index, source_index in enumerate(visible_positions):
        if (
            characters[source_index] not in "‘’´ʹ"
            or source_index in paired_quote_positions
            or visible_index == 0
        ):
            continue
        following = (
            characters[visible_positions[visible_index + 1]]
            if visible_index + 1 < len(visible_positions)
            else None
        )
        previous = characters[visible_positions[visible_index - 1]]
        previous_visible = (
            characters[visible_positions[visible_index - 2]]
            if visible_index >= 2
            else None
        )
        valid_preceding = previous.isdigit() or (
            previous == "N"
            and (
                following is None
                or following in "ACGT:"
                or (
                    previous_visible == "·"
                    and following in " =,;:.)\t\r\n"
                )
            )
        )
        if valid_preceding and (following is None or following in allowed_following):
            characters[source_index] = "′"
    return "".join(characters)


def normalize_space(value: str) -> str:
    # Publisher author metadata can contain U+200B as an invisible word-break
    # hint (for example immediately before a CRediT role). U+00AD is likewise
    # a discretionary line-break hint, not an authored chemical hyphen. Neither
    # is matched by ``\s`` and neither may leak into canonical text.
    # A few publisher archives double-encode a nonbreaking-space entity as
    # ``&amp;nbsp;``.  The HTML parser therefore exposes the literal text
    # ``&nbsp;`` instead of whitespace.  Treat only these spacing entities as
    # layout whitespace so entity syntax cannot leak into canonical prose.
    value = re.sub(
        r"&(?:nbsp|#0*160|#x0*a0);",
        "\u00a0",
        value,
        flags=re.IGNORECASE,
    )
    value = (
        unicodedata.normalize("NFC", value)
        .replace("\u200b", "")
        .replace("\u00ad", "")
    )
    # Expand only the standard typographic Latin ligatures.  Compatibility
    # normalization would also fold scientific superscripts and other symbols,
    # but these presentation glyphs should remain searchable as ordinary text.
    value = value.translate(
        str.maketrans(
            {
                "ﬀ": "ff",
                "ﬁ": "fi",
                "ﬂ": "fl",
                "ﬃ": "ffi",
                "ﬄ": "ffl",
                "ﬅ": "st",
                "ﬆ": "st",
            }
        )
    )
    value = _normalize_scientific_prime_marks(value)
    value = _normalize_scientific_caret(value)
    return SPACE_PATTERN.sub(" ", value).strip()


def slugify(value: str) -> str:
    value = unicodedata.normalize("NFKD", value)
    value = "".join(character for character in value if not unicodedata.combining(character))
    value = re.sub(r"[^A-Za-z0-9]+", "-", value).strip("-").lower()
    return value or "section"


def _tag(element: Any) -> str:
    if not isinstance(element.tag, str):
        return ""
    return element.tag.rsplit("}", 1)[-1].lower()


def _rsc_silverchair_content_root(element: Any) -> Any | None:
    """Return one exact RSC/Silverchair full-text content container.

    This archived dialect has no semantic ``article`` wrapper.  Authenticate
    it with the RSC DOI namespace, Silverchair title/access signatures, a
    contiguous numbered figure stream, its visual abstract, semantic tables,
    and the terminal References heading before enabling any dialect repair.
    """

    document = element.getroottree().getroot()
    titles = [
        title
        for title in document.xpath(".//h1[@id]")
        if re.fullmatch(r"aria\d+", title.get("id") or "", re.IGNORECASE)
        and len(title.xpath('./span/i[@title="Open Access"]')) == 1
    ]
    doi_values = {
        normalize_space(anchor.get("href") or "")
        for anchor in document.xpath('.//a[@href]')
        if re.fullmatch(
            r"https://doi\.org/10\.1039/[A-Za-z0-9][A-Za-z0-9._;()/:+-]*",
            normalize_space(anchor.get("href") or ""),
            flags=re.IGNORECASE,
        )
    }
    content_tabs = document.xpath('.//*[@id="ContentTab"]')
    if len(titles) != 1 or len(doi_values) != 1 or len(content_tabs) != 1:
        return None
    reference_headings = [
        heading
        for heading in content_tabs[0].xpath('.//h2[@id]')
        if plain_text(heading).casefold() in {"references", "notes and references"}
        and re.fullmatch(r"\d+", heading.get("id") or "")
    ]
    if len(reference_headings) != 1:
        return None
    root = reference_headings[0].getparent()
    if root is None or element is not root and not any(
        ancestor is root for ancestor in element.iterancestors()
    ):
        # Callers commonly pass the document or a broad content ancestor.
        if element is not document and not any(
            ancestor is element for ancestor in root.iterancestors()
        ):
            return None
    numbered_figures = [
        int(match.group(1))
        for figure in root.xpath('./figure[@id]')
        if (match := re.fullmatch(
            r"figure-(\d+)", figure.get("id") or "", re.IGNORECASE
        ))
        and len(figure.xpath('.//img[starts-with(@src, "data:image/")]')) == 1
    ]
    if sorted(numbered_figures) != list(range(1, len(numbered_figures) + 1)):
        return None
    visual_abstracts = root.xpath(
        './div/figure[@id="visual-abstract"][h2[normalize-space()="Visual Abstract"]]'
    )
    table_figures = [
        container
        for container in root.xpath('./div/*[self::figure or self::div]')
        if (
            re.fullmatch(
                r"(?:table-|tbl)\d+", container.get("id") or "", re.IGNORECASE
            )
            or re.fullmatch(
                r"tab\d+\s+", container.get("content-id") or "", re.IGNORECASE
            )
        )
        and bool(container.xpath(".//table"))
    ]
    if not numbered_figures or len(visual_abstracts) != 1 or not table_figures:
        return None
    return root


def _rsc_silverchair_table_details(container: Any) -> dict[str, Any] | None:
    """Return the exact visible table from an authenticated RSC wrapper."""

    root = _rsc_silverchair_content_root(container)
    identifier = re.fullmatch(
        r"(?:table-|tbl)(?P<number>\d+)", container.get("id") or "", re.IGNORECASE
    ) or re.fullmatch(
        r"tab(?P<number>\d+)\s+", container.get("content-id") or "", re.IGNORECASE
    )
    if root is None or identifier is None or _tag(container) not in {"figure", "div"}:
        return None
    number = int(identifier.group("number"))
    children = [child for child in container if isinstance(child.tag, str)]
    if [_tag(child) for child in children] != ["div", "div", "div", "div"]:
        return None
    title, visible_wrapper, hidden_wrapper, controls = children
    labels = title.xpath(f'./span[@id="label-tab{number}"]')
    captions = title.xpath(f'./div[@id="caption-tab{number}"]/p')
    visible_tables = visible_wrapper.xpath(
        './table[@role="table" or @role="presentation"]'
    )
    hidden_tables = hidden_wrapper.xpath('./table[@aria-hidden="true"]')
    control_links = controls.xpath('./a[@href]')
    if (
        title.get("id") != f"tab{number}"
        or len(labels) != 1
        or plain_text(labels[0]).casefold() != f"table {number}".casefold()
        or len(captions) != 1
        or not plain_text(captions[0])
        or len(visible_tables) != 1
        or normalize_space(visible_tables[0].get("aria-labelledby") or "")
        != f"label-tab{number}"
        or normalize_space(visible_tables[0].get("aria-describedby") or "")
        != f"caption-tab{number}"
        or (
            len(hidden_tables) != 1
            and (len(hidden_wrapper) != 0 or plain_text(hidden_wrapper))
        )
        or len(control_links) != 1
        or normalize_space(control_links[0].get("aria-label") or "").casefold()
        != f"view large table {number}".casefold()
    ):
        return None
    return {
        "number": number,
        "title": title,
        "label": labels[0],
        "caption": captions[0],
        "visible_wrapper": visible_wrapper,
        "hidden_wrapper": hidden_wrapper,
        "table": visible_tables[0],
    }


def _normalize_rsc_silverchair_snapshot(document: Any) -> None:
    """Expose exact RSC semantic tables to the common table parser."""

    root = _rsc_silverchair_content_root(document)
    if root is None:
        return
    table_figures = [
        container
        for container in root.xpath('./div/*[self::figure or self::div]')
        if re.fullmatch(
            r"table-\d+", container.get("id") or "", re.IGNORECASE
        )
        or re.fullmatch(
            r"tab\d+\s+", container.get("content-id") or "", re.IGNORECASE
        )
    ]
    details = [_rsc_silverchair_table_details(figure) for figure in table_figures]
    if not details or any(item is None for item in details):
        return
    numbers = [item["number"] for item in details if item is not None]
    if sorted(numbers) != list(range(1, len(numbers) + 1)):
        return
    for figure, item in zip(table_figures, details, strict=True):
        assert item is not None
        number = item["number"]
        header = etree.Element("header")
        header.text = plain_text(item["label"])
        _append_inline_copy(header, item["caption"])
        figure.replace(item["title"], header)
        figure.remove(item["hidden_wrapper"])
        figure.tag = "figure"
        figure.set("id", f"tbl{number}")


def _pnas_silverchair_root(document: Any) -> Any | None:
    """Return one exact semantic PNAS/Silverchair article snapshot.

    PNAS archives expose authored prose as ``div[role=paragraph]`` rather than
    HTML paragraphs and expose the bibliography as an ARIA list.  The normal
    conservative walker intentionally ignores those generic layout shapes.
    Require the complete publisher signature before recovering their semantics
    so an unrelated Silverchair page cannot have interface DIVs promoted into
    article content.
    """

    roots = [document] if _tag(document) == "article" else document.xpath(".//article")
    if len(roots) != 1:
        return None
    root = roots[0]
    if len(root.xpath(".//h1")) != 1:
        return None
    doi_links = [
        link
        for link in root.xpath('.//a[@href]')
        if re.fullmatch(
            r"https://doi\.org/10\.1073/pnas\.[A-Za-z0-9._;()/:+-]+",
            normalize_space(link.get("href") or ""),
            flags=re.IGNORECASE,
        )
    ]
    if not doi_links:
        return None
    body = root.xpath(
        './section[@id="bodymatter" and @property="articleBody" and @typeof="Text"]'
    )
    bibliography = root.xpath(
        './section[@id="backmatter"]//section[@id="bibliography" '
        'and @role="doc-bibliography"]'
    )
    if len(body) != 1 or len(bibliography) != 1:
        return None
    headings = bibliography[0].xpath('./h2[normalize-space()="References"]')
    listings = bibliography[0].xpath(
        './div[@id="bibliography-collapsible-text"]'
    )
    if len(headings) != 1 or len(listings) != 1:
        return None
    list_role = normalize_space(listings[0].get("role") or "")
    if list_role not in {"", "list"}:
        return None
    items = listings[0].xpath('./div')
    if not items:
        return None
    for number, item in enumerate(items, 1):
        item_role = normalize_space(item.get("role") or "")
        if item_role != ("listitem" if list_role == "list" else ""):
            return None
        children = [child for child in item if isinstance(child.tag, str)]
        reference_id = children[1].get("id") or ""
        expected_reference_ids = {f"r{number}", f"ref{number}", f"B{number}"}
        # Older HighWire-to-Silverchair migrations occasionally leave an
        # opaque hexadecimal DOM identifier on a reference whose original
        # anchor was absent.  Accept only that exact legacy identifier shape;
        # an ordinary noncontiguous numbered identifier must still fail the
        # dialect authentication below.
        legacy_opaque_reference_id = re.fullmatch(
            r"N0x[0-9a-f]+-0x[0-9a-f]+", reference_id, re.IGNORECASE
        )
        if (
            len(children) != 2
            or _tag(children[0]) != "div"
            or plain_text(children[0]) != str(number)
            or _tag(children[1]) != "div"
            or (
                reference_id not in expected_reference_ids
                and legacy_opaque_reference_id is None
            )
        ):
            return None
    return root


def _normalize_pnas_silverchair_snapshot(document: Any) -> None:
    """Recover exact PNAS prose while keeping embedded SI out of the article."""

    root = _pnas_silverchair_root(document)
    if root is None:
        return
    root.set("data-extraction-dialect", "pnas-silverchair")
    body = root.xpath('./section[@id="bodymatter"]')[0]

    alert_headings = [
        heading
        for heading in root.xpath('./div[@id="abstracts"]//h3')
        if plain_text(heading).casefold() == "sign up for pnas alerts."
    ]
    if len(alert_headings) == 1:
        alert = alert_headings[0]
        for _ in range(3):
            parent = alert.getparent()
            if parent is None:
                break
            alert = parent
        if (
            _tag(alert) == "div"
            and not alert.xpath(".//section")
            and re.fullmatch(
                r"sign up for pnas alerts\.\s*get alerts for new articles, or get "
                r"an alert when an article is cited\.\s*learn more",
                plain_text(alert).casefold(),
            )
        ):
            parent = alert.getparent()
            if parent is not None:
                parent.remove(alert)

    # PNAS embeds the full SI beneath the article body as convenience content.
    # Its archived PDF is independently inventoried and is authoritative for
    # that content, so remove only the publisher's exact SI IDs/headings here.
    for section in body.xpath('.//section[@id]'):
        headings = section.xpath('./h2')
        if re.fullmatch(r"sec-\d+", section.get("id") or "") and len(headings) == 1 and plain_text(headings[0]).casefold() == (
            "si materials and methods"
        ):
            parent = section.getparent()
            if parent is not None:
                parent.remove(section)
    for figure in body.xpath('.//figure[@id]'):
        if re.fullmatch(r"sfig\d+", figure.get("id") or "", re.IGNORECASE):
            parent = figure.getparent()
            if parent is not None:
                parent.remove(figure)
    for wrapper in body.xpath('.//div[@id] | .//figure[@id]'):
        if re.fullmatch(r"st\d+", wrapper.get("id") or "", re.IGNORECASE):
            parent = wrapper.getparent()
            if parent is not None:
                parent.remove(wrapper)
    # Some migrated legacy records retain a failed inline-SI import whose
    # entire payload is a publisher error message for each missing historical
    # media dependency.  The separately archived supplements are authoritative;
    # remove only this exact all-error section so its empty heading and UI noise
    # do not enter the article.
    for section in body.xpath('./div/section[@id="sec-4"]'):
        headings = section.xpath('./h2[normalize-space()="Supplementary Material"]')
        wrappers = section.xpath("./div")
        children = (
            [child for child in wrappers[0] if isinstance(child.tag, str)]
            if len(wrappers) == 1
            else []
        )
        if (
            len(headings) == 1
            and children
            and _tag(children[0]) == "div"
            and plain_text(children[0]).casefold() == "supporting information"
            and all(
                _tag(child) == "span"
                and re.fullmatch(
                    r"Media \(pnas_[A-Za-z0-9._-]+\) is missing or otherwise invalid\.",
                    plain_text(child),
                )
                for child in children[1:]
            )
        ):
            section.getparent().remove(section)

    # Preserve the original labels of authenticated PNAS download cards once.
    # Download buttons and file-size controls are UI; the item labels identify
    # the authored supporting material and must survive alongside its files.
    # Legacy PNAS records used the same card for PDFs, HTML tables, and raster
    # figures, with either one filename row or two duplicate type/name rows.
    for section in root.xpath(
        './section[@id="backmatter"]//section[@id="supplementary-materials"]'
    ):
        headings = section.xpath("./h2")
        cards = section.xpath("./div")
        exact_cards = True
        card_labels: list[tuple[Any, str]] = []
        for card in cards:
            children = [child for child in card if isinstance(child.tag, str)]
            metadata = children[0].xpath("./div") if len(children) == 2 else []
            items = children[1].xpath("./ul/li") if len(children) == 2 else []
            links = items[0].xpath("./a[@download]") if len(items) == 2 else []
            href = normalize_space(links[0].get("href") or "") if links else ""
            download_name = normalize_space(links[0].get("download") or "") if links else ""
            metadata_values = [plain_text(value) for value in metadata]
            metadata_matches = bool(
                len(metadata_values) == 1
                or (
                    len(metadata_values) == 2
                    and (
                        metadata_values[0] == metadata_values[1]
                        or metadata_values[0].casefold()
                        == f"{metadata_values[1]} (pdf)".casefold()
                    )
                )
            )
            exact_cards = exact_cards and (
                [_tag(child) for child in children] == ["div", "div"]
                and len(card) == 2
                and len(metadata) in {1, 2}
                and len(children[0]) == len(metadata)
                and len(children[1]) == 1
                and len(children[1][0]) == 2
                and len(items) == 2
                and len(items[0]) == 1
                and len(items[1]) == 0
                and all(len(node) == 0 for node in metadata)
                and all(
                    not (node.text or "").strip()
                    for node in [card, *children, children[1][0], items[0]]
                )
                and all(
                    not (node.tail or "").strip()
                    for node in [card, *children, *metadata, children[1][0], *items, *links]
                )
                and all(metadata_values)
                and metadata_matches
                and len(links) == 1
                and len(links[0]) == 0
                and plain_text(links[0]).casefold() == "download"
                and re.fullmatch(
                    r"/doi/suppl/10\.1073/pnas\.[A-Za-z0-9._;()/:+-]+/"
                    r"suppl_file/[A-Za-z0-9._;() -]+\.(?:pdf|html?|jpe?g|png|gif|tiff?|xlsx?)",
                    href,
                    flags=re.IGNORECASE,
                )
                is not None
                and download_name
                and href.casefold().endswith("/" + download_name.casefold())
                and re.fullmatch(r"(?:\d+(?:\.\d+)?|\.\d+)\s+(?:KB|MB|GB)", plain_text(items[1]))
                is not None
            )
            if metadata_values:
                card_labels.append((card, metadata_values[0]))
        if (
            len(headings) == 1
            and plain_text(headings[0]).casefold() == "supporting information"
            and cards
            and exact_cards
        ):
            for card, label in card_labels:
                # Retain the original card's position/locator. Links to the
                # archived files are supplied by supplement inventory, without
                # guessing renamed local filenames from publisher URLs here.
                card.clear()
                card.tag = "p"
                card.text = label

        # Newer PNAS snapshots sometimes wrap the same exact download card in
        # a numbered subsection whose h3 is the authored material label.  Keep
        # that label once, but discard the Download control and file-size UI.
        for nested in section.xpath('./section[@id]'):
            nested_headings = nested.xpath('./h3')
            nested_cards = nested.xpath('./div')
            if (
                re.fullmatch(r"sec-\d+-\d+", nested.get("id") or "") is None
                or len(nested_headings) != 1
                or len(nested_cards) != 1
            ):
                continue
            label = plain_text(nested_headings[0])
            card = nested_cards[0]
            children = [child for child in card if isinstance(child.tag, str)]
            metadata = children[0].xpath('./div') if len(children) == 2 else []
            items = children[1].xpath('./ul/li') if len(children) == 2 else []
            links = items[0].xpath('./a[@download]') if len(items) == 2 else []
            href = normalize_space(links[0].get('href') or '') if links else ''
            download_name = (
                normalize_space(links[0].get('download') or '') if links else ''
            )
            if not (
                label
                and [_tag(child) for child in children] == ['div', 'div']
                and len(card) == 2
                and len(metadata) in {1, 2}
                and len(children[0]) == len(metadata)
                and len(children[1]) == 1
                and len(children[1][0]) == 2
                and len(items) == 2
                and len(items[0]) == 1
                and len(items[1]) == 0
                and all(len(node) == 0 for node in metadata)
                and all(
                    not (node.text or '').strip()
                    for node in [card, *children, children[1][0], items[0]]
                )
                and all(
                    not (node.tail or '').strip()
                    for node in [
                        card,
                        *children,
                        *metadata,
                        children[1][0],
                        *items,
                        *links,
                    ]
                )
                and all(plain_text(node) for node in metadata)
                and len(links) == 1
                and len(links[0]) == 0
                and plain_text(links[0]).casefold() == 'download'
                and re.fullmatch(
                    r"/doi/suppl/10\.1073/pnas\.[A-Za-z0-9._;()/:+-]+/"
                    r"suppl_file/[A-Za-z0-9._;() -]+\."
                    r"(?:pdf|html?|jpe?g|png|gif|tiff?|xlsx?)",
                    href,
                    flags=re.IGNORECASE,
                )
                is not None
                and download_name
                and href.casefold().endswith('/' + download_name.casefold())
                and re.fullmatch(
                    r"(?:\d+(?:\.\d+)?|\.\d+)\s+(?:KB|MB|GB)",
                    plain_text(items[1]),
                )
                is not None
            ):
                continue
            nested.clear()
            nested.tag = 'p'
            nested.text = label

    authored_roots = [
        *root.xpath('./div[@id="abstracts"]'),
        body,
        *root.xpath(
            './section[@id="backmatter"]//section[@id="data-availability" '
            'and h2[normalize-space()="Data Availability"]]'
        ),
        *root.xpath(
            './section[@id="backmatter"]//section[@id="acknowledgments"]'
        ),
    ]
    for authored_root in authored_roots:
        for paragraph in authored_root.xpath('.//div[@role="paragraph"]'):
            # Legacy PNAS snapshots nest complete, numbered display cards
            # inside prose. Keep their authored semantics as sibling cards so
            # inline paragraph rendering cannot duplicate captions or tables.
            cards = []
            for child in list(paragraph):
                labels = child.xpath('./header/div') if _tag(child) == 'div' else []
                displays = child.xpath('./figure[@id] | ./div[@id][.//table]')
                if (
                    len(labels) != 1 or len(displays) != 1
                    or re.fullmatch(r'(?:Fig\.|Figure|Table|Scheme)\s+\d+\.', plain_text(labels[0])) is None
                    or len([node for node in child if isinstance(node.tag, str)]) != 2
                ):
                    continue
                tail = child.tail or ''
                previous = child.getprevious()
                if previous is None:
                    paragraph.text = (paragraph.text or '') + tail
                else:
                    previous.tail = (previous.tail or '') + tail
                child.tail = None
                paragraph.remove(child)
                cards.append(child)
            following = paragraph
            for card in cards:
                following.addnext(card)
                following = card
            paragraph.tag = "p"
    for note in root.xpath(
        './section[@id="backmatter"]//section[@id="footnotes"]/'
        'div[@role="doc-footnote"]'
    ):
        note.tag = "p"

    # The outer article also contains metrics, citations, download, and share
    # panes.  Their headings are publisher controls, not authored sections.
    allowed_heading_roots = [
        *root.xpath('./div[@id="abstracts"]'),
        body,
        *root.xpath('./section[@id="backmatter"]'),
    ]
    for heading in root.xpath('.//h2 | .//h3 | .//h4'):
        if not any(
            heading is allowed or allowed in heading.iterancestors()
            for allowed in allowed_heading_roots
        ):
            heading.tag = "div"


def _aha_silverchair_root(document: Any) -> Any | None:
    """Return one exact AHA/Silverchair semantic article snapshot.

    AHA archives use the same broad Silverchair shell as PNAS, but their
    article body is nested below an anonymous direct ``div``, their numbered
    figures use ``FIG#`` identifiers, and their bibliography entries use
    ``R#-<article suffix>`` identifiers.  Require all of those independent
    signals before exposing generic role-paragraph divs as authored prose.
    """

    roots = [document] if _tag(document) == "article" else document.xpath(".//article")
    if len(roots) != 1:
        return None
    root = roots[0]
    titles = root.xpath("./header//h1")
    doi_links = [
        link
        for link in root.xpath('./header//a[@href]')
        if re.fullmatch(
            r"https://doi\.org/10\.1161/[A-Za-z0-9._;()/:+-]+",
            normalize_space(link.get("href") or ""),
            flags=re.IGNORECASE,
        )
        and plain_text(link).casefold()
        == normalize_space(link.get("href") or "").casefold()
    ]
    abstracts = root.xpath(
        './div/div[@id="abstracts"]//section[@id="abstract" '
        'and @property="abstract" and @typeof="Text" '
        'and @role="doc-abstract"]'
    )
    bodies = root.xpath(
        './div/section[@id="bodymatter" and @property="articleBody" '
        'and @typeof="Text"]'
    )
    bibliographies = root.xpath(
        './div/section[@id="backmatter"]/div/section[@id="bibliography" '
        'and @role="doc-bibliography"]'
    )
    if (
        len(titles) != 1
        or not plain_text(titles[0])
        or len(doi_links) != 1
        or len(abstracts) != 1
        or len(bodies) != 1
        or len(bibliographies) != 1
        or len(bibliographies[0].xpath('./h2[normalize-space()="References"]'))
        != 1
    ):
        return None

    bibliography = bibliographies[0]
    listings = bibliography.xpath('./div[@id="bibliography-collapsible-text"]')
    if len(listings) != 1:
        return None
    items = listings[0].xpath("./div")
    if not items:
        return None
    article_suffix = ""
    for number, item in enumerate(items, 1):
        children = [child for child in item if isinstance(child.tag, str)]
        identifier_match = (
            re.fullmatch(
                rf"R{number}-(?P<suffix>[A-Za-z0-9._-]+)",
                children[1].get("id") or "",
                flags=re.IGNORECASE,
            )
            if len(children) == 2
            else None
        )
        if (
            len(children) != 2
            or _tag(children[0]) != "div"
            or plain_text(children[0]) != f"{number}."
            or _tag(children[1]) != "div"
            or identifier_match is None
        ):
            return None
        suffix = identifier_match.group("suffix").casefold()
        if not article_suffix:
            article_suffix = suffix
        elif suffix != article_suffix:
            return None

    figures = bodies[0].xpath('.//figure[@id]')
    if not figures:
        return None
    for number, figure in enumerate(figures, 1):
        children = [child for child in figure if isinstance(child.tag, str)]
        image = children[0] if len(children) == 2 else None
        caption = children[1] if len(children) == 2 else None
        labels = caption.xpath("./b[1]") if caption is not None else []
        if (
            (figure.get("id") or "").casefold() != f"fig{number}"
            or image is None
            or _tag(image) != "img"
            or not normalize_space(image.get("src") or "")
            .casefold()
            .startswith("data:image/")
            or caption is None
            or _tag(caption) != "figcaption"
            or len(labels) != 1
            or re.fullmatch(
                rf"Figure\s+{number}\.\s*",
                plain_text(labels[0]),
                flags=re.IGNORECASE,
            )
            is None
            or not normalize_space(labels[0].tail or "")
        ):
            return None
    return root


def _normalize_aha_silverchair_snapshot(document: Any) -> None:
    """Expose authored AHA role-paragraph DIVs to the common walker."""

    root = _aha_silverchair_root(document)
    if root is None:
        return
    root.set("data-extraction-dialect", "aha-silverchair")
    bibliography = root.xpath(
        './div/section[@id="backmatter"]/div/section[@id="bibliography"]'
    )[0]
    authored_roots = [
        *root.xpath('./div/div[@id="abstracts"]'),
        *root.xpath('./div/section[@id="bodymatter"]'),
        *root.xpath(
            './div/section[@id="backmatter"]/div/'
            'section[@id="acknowledgments"]'
        ),
    ]
    # This AHA snapshot nests each semantic figure in an otherwise empty
    # direct DIV inside the prose DIV that cites it.  Figures are emitted
    # independently, so lift only that authenticated wrapper beside its prose
    # block; otherwise the complete caption is duplicated at the end of the
    # surrounding paragraph.
    for authored_root in authored_roots:
        for paragraph in authored_root.xpath('.//div[@role="paragraph"][.//figure]'):
            parent = paragraph.getparent()
            if parent is None:
                continue
            wrappers = [
                child
                for child in paragraph
                if _tag(child) == "div"
                and len([node for node in child if isinstance(node.tag, str)]) == 1
                and _tag(next(node for node in child if isinstance(node.tag, str)))
                == "figure"
                and not normalize_space(child.text or "")
                and not normalize_space(child.tail or "")
            ]
            insert_at = parent.index(paragraph) + 1
            for wrapper in wrappers:
                paragraph.remove(wrapper)
                parent.insert(insert_at, wrapper)
                insert_at += 1
    for authored_root in authored_roots:
        for paragraph in authored_root.xpath('.//div[@role="paragraph"]'):
            if paragraph is bibliography or bibliography in paragraph.iterancestors():
                continue
            paragraph.tag = "p"

    body = root.xpath('./div/section[@id="bodymatter"]')[0]
    wrappers = body.xpath("./div")
    if len(wrappers) == 1:
        wrapper = wrappers[0]
        direct_children = [child for child in wrapper if isinstance(child.tag, str)]
        if (
            direct_children
            and _tag(direct_children[0]) == "p"
            and not wrapper.xpath("./h2 | ./h3 | ./h4")
        ):
            heading = etree.Element("h2")
            heading.text = "Introduction"
            wrapper.insert(0, heading)


def _pdi_semantic_root(document: Any) -> Any | None:
    """Return one exact Peritoneal Dialysis International article fragment.

    The archived PDI/Literatum dialect is already article-focused, but it
    serializes authored prose as ``div[role=paragraph]`` and its bibliography
    as contiguous ``div#bibrN-pdi-*`` entries.  Authenticate the complete
    local structure before enabling either semantic recovery so unrelated
    Atypon controls cannot be promoted as publication content.
    """

    roots = [document] if _tag(document) == "article" else document.xpath(".//article")
    if len(roots) != 1:
        return None
    root = roots[0]
    titles = root.xpath("./header/h1")
    doi_links = [
        link
        for link in root.xpath('./header//a[@href]')
        if re.fullmatch(
            r"https://doi\.org/10\.3747/pdi\.\d{4}\.\d+",
            normalize_space(link.get("href") or ""),
            flags=re.IGNORECASE,
        )
        and plain_text(link).casefold()
        == normalize_space(link.get("href") or "").casefold()
    ]
    body = root.xpath(
        './div/section[@id="bodymatter" and @property="articleBody" and @typeof="Text"]'
    )
    bibliographies = root.xpath(
        './div/section[@id="backmatter"]/div/section[@id="bibliography" '
        'and @role="doc-bibliography"]'
    )
    if (
        len(titles) != 1
        or len(doi_links) != 1
        or len(body) != 1
        or len(bibliographies) != 1
        or len(bibliographies[0].xpath('./h2[normalize-space()="References"]'))
        != 1
    ):
        return None
    entries = bibliographies[0].xpath('./div/div/div[@id]')
    if not entries:
        return None
    identifiers = [entry.get("id") or "" for entry in entries]
    matches = [
        re.fullmatch(
            r"bibr(?P<number>\d+)-(?P<slug>pdi-\d{4}-\d+)",
            identifier,
            flags=re.IGNORECASE,
        )
        for identifier in identifiers
    ]
    if any(match is None for match in matches):
        return None
    assert all(match is not None for match in matches)
    if [int(match.group("number")) for match in matches] != list(
        range(1, len(entries) + 1)
    ) or len({match.group("slug").casefold() for match in matches}) != 1:
        return None
    figure_ids = [
        match.group("number")
        for figure in root.xpath('.//figure[@id][img[starts-with(@src, "data:image/")]]')
        if (match := re.fullmatch(
            r"fig(?P<number>\d+)-(?P<slug>pdi-\d{4}-\d+)",
            figure.get("id") or "",
            flags=re.IGNORECASE,
        ))
    ]
    if not figure_ids or [int(value) for value in figure_ids] != list(
        range(1, len(figure_ids) + 1)
    ):
        return None
    return root


def _normalize_pdi_semantic_snapshot(document: Any) -> None:
    """Expose authored PDI role-paragraph DIVs to the conservative walker."""

    root = _pdi_semantic_root(document)
    if root is None:
        return
    root.set("data-extraction-dialect", "pdi-semantic")
    bibliography = root.xpath(
        './div/section[@id="backmatter"]/div/section[@id="bibliography"]'
    )[0]
    for paragraph in root.xpath('.//div[@role="paragraph"]'):
        if paragraph is bibliography or bibliography in paragraph.iterancestors():
            continue
        paragraph.tag = "p"
    body = root.xpath('./div/section[@id="bodymatter"]')[0]
    wrappers = body.xpath("./div")
    if len(wrappers) == 1:
        wrapper = wrappers[0]
        direct_children = [child for child in wrapper if isinstance(child.tag, str)]
        if (
            direct_children
            and _tag(direct_children[0]) == "p"
            and not wrapper.xpath("./h2 | ./h3 | ./h4")
        ):
            heading = etree.Element("h2")
            heading.text = "Introduction"
            wrapper.insert(0, heading)


_MDPI_ARTICLE_ID = re.compile(
    r"mdpi-article-(?P<slug>[a-z0-9-]+)-(?P<volume>\d+)-(?P<article>\d+)",
    re.IGNORECASE,
)
_MDPI_PREFIX = re.compile(
    r"(?P<slug>[a-z0-9-]+)-(?P<volume>\d+)-(?P<article>\d+)",
    re.IGNORECASE,
)


def _mdpi_article_doi_links(candidate: Any) -> list[Any]:
    """Return MDPI DOI links from article metadata, excluding references."""

    return [
        link
        for link in candidate.xpath(
            './/a[starts-with(translate(@href, "HTTPSDOIORG", "httpsdoiorg"), '
            '"https://doi.org/10.3390/")]'
        )
        if not any(_tag(ancestor) == "section" for ancestor in link.iterancestors())
    ]


def _normalize_identifier_light_mdpi_snapshot(document: Any) -> None:
    """Restore semantics in one older self-contained MDPI page dialect.

    These archived pages retain strong publisher identity metadata, semantic
    article sections, complete embedded figure images, and authored caption
    labels, but omit the article/figure identifiers used by newer MDPI
    snapshots and serialize ordinary paragraphs as anonymous ``div`` nodes.
    Authenticate the complete local signature before adding deterministic IDs.
    """

    root = document.getroottree().getroot()
    semantic_article: Any | None = None
    articles = root.xpath("./body/article")
    if articles:
        # One older identifier-light MDPI export preserves an otherwise
        # anonymous semantic ``article`` around the same attribute-free
        # content div used by the flatter dialect.  Authenticate the complete
        # publisher/URL/DOI/section/figure signature below before accepting
        # this wrapper; an attributed or multi-child article remains outside
        # this narrowly reviewed normalization.
        if len(articles) != 1 or articles[0].attrib:
            return
        article_children = articles[0].xpath("./div[not(@*)]")
        if len(article_children) != 1:
            return
        semantic_article = articles[0]
        candidate = article_children[0]
    else:
        candidates = root.xpath("./body/div[not(@*)]")
        if len(candidates) != 1:
            return
        candidate = candidates[0]
    publishers = candidate.xpath(
        './span[@itemprop="publisher" and '
        '@content="Multidisciplinary Digital Publishing Institute"]'
    )
    urls = candidate.xpath('./span[@itemprop="url" and @content]')
    titles = candidate.xpath('./h1[@itemprop="name"]')
    doi_links = _mdpi_article_doi_links(candidate)
    if (
        len(publishers) != 1
        or len(urls) != 1
        or len(titles) != 1
        or not plain_text(titles[0])
        or len(doi_links) != 1
    ):
        return

    url_match = re.fullmatch(
        r"https://www\.mdpi\.com/\d{4}-\d{3,4}/"
        r"(?P<volume>\d+)/(?P<issue>\d+)/(?P<article>\d+)",
        normalize_space(urls[0].get("content") or ""),
        flags=re.IGNORECASE,
    )
    doi_match = re.fullmatch(
        r"https://doi\.org/10\.3390/(?P<stem>[a-z0-9-]+)",
        normalize_space(doi_links[0].get("href") or ""),
        flags=re.IGNORECASE,
    )
    if url_match is None or doi_match is None:
        return
    doi_suffix = (
        f"{int(url_match.group('volume')):02d}"
        f"{int(url_match.group('issue')):02d}"
        f"{url_match.group('article')}"
    )
    stem = doi_match.group("stem")
    if not stem.casefold().endswith(doi_suffix.casefold()):
        return
    slug = stem[: -len(doi_suffix)]
    if re.fullmatch(r"[a-z][a-z0-9-]*", slug, flags=re.IGNORECASE) is None:
        return
    prefix = f"{slug}-{int(url_match.group('volume'))}-{url_match.group('article')}"

    introductions = candidate.xpath(
        './div//section[@id="1Introduction" and @type="intro"]'
    )
    references = candidate.xpath(
        './/section[@id="html-references_list"]'
        '[h2[normalize-space()="References"] and ol/li]'
    )
    if (
        len(introductions) != 1
        or len(introductions[0].xpath('./h2[normalize-space()="1. Introduction"]'))
        != 1
        or len(references) != 1
    ):
        return

    figures = candidate.xpath(".//figure")
    if not figures:
        return
    numbered_figures: list[tuple[Any, str, int]] = []
    numbers_by_kind: dict[str, list[int]] = defaultdict(list)
    for figure in figures:
        children = [child for child in figure if isinstance(child.tag, str)]
        if [_tag(child) for child in children] != ["div", "div"]:
            return
        images = children[0].xpath('.//img[starts-with(@src, "data:image/")]')
        labels = children[1].xpath("./b[1]")
        label_match = (
            re.fullmatch(
                r"\s*(?P<kind>Figure|Scheme)\s+(?P<number>\d+)\.\s*",
                plain_text(labels[0]),
                flags=re.IGNORECASE,
            )
            if len(labels) == 1
            else None
        )
        # MDPI can serialize a single numbered figure as several embedded
        # raster parts (for example panels a--c followed by panel d).  The
        # asset pass composes those parts deterministically, so authenticate
        # the figure from the complete image container rather than requiring
        # exactly one raster.
        if not images or label_match is None:
            return
        kind = label_match.group("kind").casefold()
        number = int(label_match.group("number"))
        numbers_by_kind[kind].append(number)
        numbered_figures.append((figure, kind, number))
    if any(
        sorted(numbers) != list(range(1, len(numbers) + 1))
        for numbers in numbers_by_kind.values()
    ):
        return

    equation_details: list[tuple[Any, Any, str, int]] = []
    equation_numbers: list[int] = []
    for wrapper in candidate.xpath('.//div[@id]'):
        equation_match = re.fullmatch(
            r"FD(?P<number>\d+)", wrapper.get("id") or "", re.IGNORECASE
        )
        if equation_match is None:
            continue
        number = int(equation_match.group("number"))
        children = [child for child in wrapper if isinstance(child.tag, str)]
        display_math = wrapper.xpath(
            './/*[local-name() = "math" and '
            'translate(@display, "BLOCK", "block") = "block"]'
        )
        labels = children[1].xpath("./label") if len(children) == 2 else []
        label = plain_text(labels[0]) if len(labels) == 1 else ""
        if (
            [_tag(child) for child in children] != ["div", "div"]
            or len(display_math) != 1
            or label != f"({number})"
        ):
            return
        equation_numbers.append(number)
        equation_details.append((wrapper, display_math[0], label, number))
    if equation_numbers and sorted(equation_numbers) != list(
        range(1, len(equation_numbers) + 1)
    ):
        return

    article = semantic_article if semantic_article is not None else candidate
    article.tag = "article"
    article.set("id", f"mdpi-article-{prefix}")
    introductions[0].set("id", f"sec1-{prefix}")
    for figure, kind, number in numbered_figures:
        marker = "s" if kind == "scheme" else "f"
        figure.set("id", f"{prefix}-{marker}{number:03d}")
    for wrapper, display_math, label, number in equation_details:
        replacement = etree.Element("span")
        replacement.set("id", f"e{number}")
        equation = copy.deepcopy(display_math)
        equation.tail = f" {label}"
        replacement.append(equation)
        parent = wrapper.getparent()
        if parent is not None:
            parent.replace(wrapper, replacement)


def _normalize_anonymous_mdpi_snapshot(document: Any) -> None:
    """Restore the semantic wrapper and figure tags in one flat MDPI dialect.

    Some archived self-contained MDPI pages retain the publisher's stable
    section and figure identifiers, exact DOI link, and two-part figure
    structure, but serialize the article wrapper and every numbered figure as
    anonymous ``div`` elements.  Recover only that complete publisher
    signature so the normal MDPI paragraph and figure handling can run; an
    ordinary layout ``div`` or a partial near miss remains untouched.
    """

    root = document.getroottree().getroot()
    articles = root.xpath(".//article")
    semantic_article: Any | None = None
    if articles:
        # A second archived MDPI dialect retains an anonymous semantic
        # ``article`` around one attribute-free content div.  The original
        # normalizer handled only the still flatter ``body > div`` form, so
        # its authored div paragraphs remained invisible to the conservative
        # body walker.  Require the same full MDPI identity signature below;
        # an ordinary or already identified article remains untouched.
        if len(articles) != 1 or articles[0].attrib:
            return
        article_children = articles[0].xpath("./div[not(@*)]")
        if len(article_children) != 1:
            return
        semantic_article = articles[0]
        candidate = article_children[0]
    else:
        candidates = root.xpath("./body/div[not(@*)]")
        if len(candidates) != 1:
            return
        candidate = candidates[0]
    if len(candidate.xpath("./h1")) != 1:
        return
    doi_links = _mdpi_article_doi_links(candidate)
    if len(doi_links) != 1:
        return
    introductions = candidate.xpath('.//section[starts-with(@id, "sec1-")]')
    if len(introductions) != 1:
        return
    introduction_id = introductions[0].get("id") or ""
    prefix_match = _MDPI_PREFIX.fullmatch(introduction_id.removeprefix("sec1-"))
    if prefix_match is None:
        return
    prefix = prefix_match.group(0)
    figure_pattern = re.compile(
        rf"{re.escape(prefix)}-f(?P<number>\d{{3}})", re.IGNORECASE
    )
    figure_nodes = [
        node
        for node in candidate.xpath(".//div[@id] | .//figure[@id]")
        if figure_pattern.fullmatch(node.get("id") or "")
    ]
    if not figure_nodes:
        return
    numbered_nodes: list[tuple[int, Any]] = []
    for node in figure_nodes:
        identifier = figure_pattern.fullmatch(node.get("id") or "")
        figure_number = int(identifier.group("number")) if identifier is not None else -1
        element_children = [
            child for child in node if isinstance(child.tag, str)
        ]
        if _tag(node) == "figure":
            semantic_captions = node.xpath("./figcaption")
            if len(semantic_captions) == 1:
                image_containers = node.xpath("./div[1]")
                caption_containers = semantic_captions
                structure_valid = (
                    len(image_containers) == 1 and len(caption_containers) == 1
                )
            elif not semantic_captions and [
                _tag(child) for child in element_children
            ] == ["div", "div"]:
                # One archived MDPI hybrid keeps the semantic ``figure`` tag
                # but flattens its caption to the same second anonymous div
                # used by the fully anonymous dialect.  Accept only that exact
                # two-div structure; the DOI, section, identifier, image, and
                # contiguous label gates below still have to match.
                image_containers = element_children[:1]
                caption_containers = element_children[1:]
                structure_valid = True
            else:
                image_containers = []
                caption_containers = []
                structure_valid = False
            labels = (
                caption_containers[0].xpath("./b[1]")
                if len(caption_containers) == 1
                else []
            )
        else:
            structure_valid = [
                _tag(child) for child in element_children
            ] == ["div", "div"]
            image_containers = element_children[:1]
            labels = (
                element_children[1].xpath("./b[1]")
                if structure_valid
                else []
            )
        label_match = (
            re.fullmatch(
                r"\s*(?:Fig(?:ure)?|Scheme)\.?\s*(\d+)\.?\s*",
                plain_text(labels[0]),
                flags=re.IGNORECASE,
            )
            if len(labels) == 1
            else None
        )
        images = (
            image_containers[0].xpath(
                './/img[starts-with(@src, "data:image/")]'
            )
            if image_containers
            else []
        )
        # A legacy MDPI archive can retain the exact semantic numbered-figure
        # card while omitting only the raster bytes.  Accept that source defect
        # only when the otherwise empty image container consists of the
        # publisher's matching display-object link and empty anchor.  The
        # extraction pipeline will then require a reviewed replacement asset
        # (normally a source-pinned PDF crop) instead of discarding the entire
        # authenticated article body.
        missing_raster_stub = False
        if (
            _tag(node) == "figure"
            and identifier is not None
            and len(image_containers) == 1
            and not images
        ):
            target = f"#fig_body_display_{prefix}-f{figure_number:03d}"
            container_children = [
                child
                for child in image_containers[0]
                if isinstance(child.tag, str)
            ]
            if len(container_children) == 1:
                wrapper = container_children[0]
                wrapper_children = [
                    child for child in wrapper if isinstance(child.tag, str)
                ]
                missing_raster_stub = (
                    _tag(wrapper) == "div"
                    and wrapper.get("href") == target
                    and len(wrapper_children) == 1
                    and _tag(wrapper_children[0]) == "a"
                    and wrapper_children[0].get("href") == target
                    and not plain_text(image_containers[0])
                )
        if (
            identifier is None
            or not structure_valid
            or not (images or missing_raster_stub)
            or label_match is None
            or int(label_match.group(1)) != int(identifier.group("number"))
        ):
            return
        numbered_nodes.append((int(identifier.group("number")), node))
    numbers = sorted(number for number, _ in numbered_nodes)
    if numbers != list(range(1, len(numbers) + 1)):
        return

    article = semantic_article if semantic_article is not None else candidate
    article.tag = "article"
    article.set("id", f"mdpi-article-{prefix}")
    for _, node in numbered_nodes:
        node.tag = "figure"


def _mdpi_snapshot_root(element: Any) -> Any | None:
    """Return one exact self-contained MDPI article snapshot, if present.

    Archived MDPI HTML preserves semantic article/section/figure identifiers
    but serializes authored paragraphs and captions as anonymous ``div``
    elements.  Requiring the article ID, a local DOI citation, the matching
    first body section, and the matching first numbered figure keeps the
    normalization below from changing ordinary layout ``div`` elements.
    """

    document = element.getroottree().getroot()
    candidates = [
        candidate
        for candidate in (document, *document.xpath(".//article[@id]"))
        if _tag(candidate) == "article"
        and _MDPI_ARTICLE_ID.fullmatch(candidate.get("id") or "")
    ]
    matched: list[Any] = []
    for candidate in candidates:
        identifier = _MDPI_ARTICLE_ID.fullmatch(candidate.get("id") or "")
        if identifier is None or len(candidate.xpath(".//h1")) != 1:
            continue
        prefix = (
            f"{identifier.group('slug')}-{identifier.group('volume')}-"
            f"{identifier.group('article')}"
        )
        doi_links = _mdpi_article_doi_links(candidate)
        if not doi_links:
            continue
        if len(candidate.xpath(f'.//section[@id="sec1-{prefix}"]')) != 1:
            continue
        if len(candidate.xpath(f'.//figure[@id="{prefix}-f001"]')) != 1:
            continue
        matched.append(candidate)
    return matched[0] if len(matched) == 1 else None


def _normalize_mdpi_snapshot(document: Any) -> None:
    """Restore paragraph and inline emphasis semantics in one MDPI dialect."""

    root = _mdpi_snapshot_root(document)
    if root is None:
        return
    for paragraph in list(root.xpath(".//p")):
        if not plain_text(paragraph):
            parent = paragraph.getparent()
            if parent is not None:
                parent.remove(paragraph)
    block_tags = {
        "div",
        "section",
        "figure",
        "table",
        "h1",
        "h2",
        "h3",
        "h4",
        "h5",
        "h6",
        "p",
        "ul",
        "ol",
        "dl",
    }
    for section in root.xpath(".//section"):
        for child in section.xpath("./div[not(@*)]"):
            if not plain_text(child) or any(
                _tag(descendant) in block_tags for descendant in child.iterdescendants()
            ):
                continue
            child.tag = "p"

    # The same archived self-contained dialect replaces authored inline
    # ``em``/``i`` elements with attribute-free ``span`` elements.  Restore
    # only spans that are genuinely inline: a span must be a leaf, must have
    # authored direct text beside it in the same parent, and must not sit
    # inside another semantic inline element.  This preserves variables,
    # species names, and journal/volume typography while leaving structural
    # one-span wrappers (for example an entire table note) unchanged.
    semantic_ancestors = {"a", "b", "em", "i", "strong", "sub", "sup"}
    for span in root.xpath(".//section//span[not(@*) and not(*)]"):
        parent = span.getparent()
        if parent is None or _tag(parent) in semantic_ancestors:
            continue
        if any(
            _tag(ancestor) in semantic_ancestors
            for ancestor in span.iterancestors()
            if ancestor is not root
        ):
            continue
        direct_text_outside_span = " ".join(
            [parent.text or "", *(child.tail or "" for child in parent)]
        )
        if not normalize_space(direct_text_outside_span):
            continue
        span.tag = "em"


def _normalize_mdpi_sample_availability(document: Any) -> None:
    """Expose one exact MDPI post-reference availability note as prose.

    Some self-contained MDPI snapshots serialize the authored Sample
    Availability statement after the bibliography as a one-row layout table.
    References are a terminal boundary for the general body walker, and the
    scientific-table extractor correctly rejects this layout shell, so the
    statement would otherwise disappear. Require the complete MDPI identity
    plus the exact References -> availability table -> copyright sibling
    sequence before converting the label to a section heading and moving that
    authored back-matter section ahead of the canonical reference boundary.
    """

    root = _mdpi_snapshot_root(document)
    if root is None or etree is None:
        return
    references = root.xpath('.//section[@id="html-references_list"]')
    copyrights = root.xpath('.//section[@id="html-copyright"]')
    if len(references) != 1 or len(copyrights) != 1:
        return
    reference_section = references[0]
    copyright_section = copyrights[0]
    sample_section = reference_section.getnext()
    if (
        sample_section is None
        or _tag(sample_section) != "section"
        or sample_section.getnext() is not copyright_section
        or sample_section.getparent() is not reference_section.getparent()
        or sample_section.attrib
    ):
        return
    sample_children = [
        child for child in sample_section if isinstance(child.tag, str)
    ]
    if len(sample_children) != 1 or _tag(sample_children[0]) != "table":
        return
    table = sample_children[0]
    rows = table.xpath("./tbody/tr | ./tr")
    if len(rows) != 1 or len(table.xpath(".//tr")) != 1:
        return
    cells = rows[0].xpath("./td")
    if len(cells) != 2 or plain_text(cells[0]):
        return
    wrappers = cells[1].xpath("./div")
    if len(wrappers) != 1 or len(
        [child for child in cells[1] if isinstance(child.tag, str)]
    ) != 1:
        return
    paragraph = wrappers[0]
    paragraph_children = [
        child for child in paragraph if isinstance(child.tag, str)
    ]
    if (
        not paragraph_children
        or paragraph_children[0] is not paragraph[0]
        or _tag(paragraph_children[0]) != "b"
        or normalize_space(paragraph.text or "")
        or plain_text(paragraph_children[0]).casefold() != "sample availability:"
    ):
        return
    label = paragraph_children[0]
    label_tail = label.tail or ""
    label.tail = None
    paragraph.remove(label)
    paragraph.text = (paragraph.text or "") + label_tail
    if not plain_text(paragraph):
        return
    paragraph.tag = "p"
    paragraph.attrib.clear()
    heading = etree.Element("h2")
    heading.text = "Sample Availability"
    sample_section.remove(table)
    sample_section.append(heading)
    sample_section.append(paragraph)
    reference_section.addprevious(sample_section)


def _normalize_mixed_inline_list_wrappers(document: Any) -> None:
    """Expose prose serialized beside one trailing list as a real paragraph.

    Some publisher snapshots serialize a method paragraph as the direct text
    and inline children of an otherwise unmarked ``div``, followed by one
    authored list.  The body walker intentionally does not treat arbitrary
    ``div`` nodes as prose, so normalize only this structurally unambiguous
    shape.  A trailing node or a second list is a near miss and is left alone.
    """

    inline_tags = {
        "a",
        "abbr",
        "b",
        "br",
        "cite",
        "code",
        "em",
        "i",
        "mark",
        "q",
        "s",
        "small",
        "span",
        "strong",
        "sub",
        "sup",
        "u",
    }
    for wrapper in document.xpath("//section/div"):
        parent = wrapper.getparent()
        children = [child for child in wrapper if isinstance(child.tag, str)]
        headings = (
            parent.xpath("./h2 | ./h3 | ./h4") if parent is not None else []
        )
        if (
            parent is None
            or _tag(parent) != "section"
            or len(headings) != 1
            or len(children) < 1
            or _tag(children[-1]) not in {"ul", "ol"}
            or any(_tag(child) in {"ul", "ol"} for child in children[:-1])
            or any(_tag(child) not in inline_tags for child in children[:-1])
            or normalize_space(children[-1].tail or "")
        ):
            continue
        prose = normalize_space(
            " ".join(
                [
                    wrapper.text or "",
                    *(
                        "".join(child.itertext()) + (child.tail or "")
                        for child in children[:-1]
                    ),
                ]
            )
        )
        if not prose:
            continue
        paragraph = html.Element("p")
        paragraph.text = wrapper.text
        wrapper.text = None
        for child in children[:-1]:
            wrapper.remove(child)
            paragraph.append(child)
        wrapper.insert(0, paragraph)


_WILEY_SUPPORTING_DISCLAIMER = (
    "Please note: The publisher is not responsible for the content or functionality "
    "of any supporting information supplied by the authors. Any queries (other than "
    "missing content) should be directed to the corresponding author for the article."
)
_WILEY_SUPPORTING_SERVICE_NOTICE = (
    "As a service to our authors and readers, this journal provides supporting "
    "information supplied by the authors. Such materials are peer reviewed and may "
    "be re-organized for online delivery, but are not copy-edited or typeset. "
    "Technical support issues arising from supporting information (other than missing "
    "files) should be addressed to the authors."
)
_WILEY_SUPPORTING_ONLINE_NOTICE = (
    "Supporting information may be found in the online version of this paper"
)
_WILEY_SUPPORTING_RETAINED_ONLINE_NOTICE = (
    "Additional Supporting Information may be found in the online version of "
    "this article."
)
_NORMALIZED_SOURCE_LOCATOR_ATTRIBUTE = "data-pip-litdb-source-locator"
_NORMALIZED_KIND_ATTRIBUTE = "data-pip-litdb-normalized-kind"
_NORMALIZED_DIALECT_ATTRIBUTE = "data-pip-litdb-normalized-dialect"


def _discard_reserved_normalization_attributes(document: Any) -> None:
    """Prevent archived markup from impersonating extractor-owned metadata."""

    for element in document.xpath(
        '//*[@data-pip-litdb-source-locator or @data-pip-litdb-normalized-kind '
        'or @data-pip-litdb-normalized-dialect]'
    ):
        element.attrib.pop(_NORMALIZED_SOURCE_LOCATOR_ATTRIBUTE, None)
        element.attrib.pop(_NORMALIZED_KIND_ATTRIBUTE, None)
        element.attrib.pop(_NORMALIZED_DIALECT_ATTRIBUTE, None)


def _normalize_structured_wiley_supporting_information(document: Any) -> None:
    """Retain descriptions and remove download chrome in one exact Wiley block.

    A legacy Wiley archive represents Supporting Information as a two-column
    download table followed by a publisher disclaimer.  The description column
    is authored semantic content, while the filename/download metadata and
    disclaimer are interface text.  Normalize only the complete publisher
    signature; malformed or differently structured tables remain untouched.
    """

    plans: list[tuple[Any, list[Any], list[tuple[Any, str]]]] = []
    link_pattern = re.compile(
        r"/action/downloadSupplement\?doi=(?P<doi>[^&]+)&file=(?P<file>[^&]+)"
    )
    doi_pattern = re.compile(
        r"10\.(?:1002|1016|1111)/[A-Za-z0-9][A-Za-z0-9._;()/:-]*"
    )
    metadata_pattern = re.compile(
        r"(?:(?:PDF|Word) document, |[A-Za-z][A-Za-z0-9.+-]*/[A-Za-z0-9.+-]+, )?"
        r"[0-9.]+ (?:KB|MB)"
    )

    for section in document.xpath("//section"):
        outer = section.xpath("./div")
        if len(outer) != 1:
            continue
        outer_children = [
            child for child in outer[0] if isinstance(child.tag, str)
        ]
        if len(outer_children) != 2 or [_tag(child) for child in outer_children] != [
            "h2",
            "div",
        ]:
            continue
        heading_nodes = outer_children[0].xpath(
            './a/div[@id="support-information-section"]/span'
        )
        if (
            len(heading_nodes) != 1
            or plain_text(heading_nodes[0]) != "Supporting Information"
        ):
            continue
        content_container = outer_children[1]
        content_id = content_container.get("id") or ""
        if (
            re.fullmatch(
                r"(?:d\d+e\d+|[a-z][a-z0-9]{6,31}-s\d{4}|"
                r"[a-z][a-z0-9]{2,31}-supinf-\d{4})",
                content_id,
                re.IGNORECASE,
            )
            is None
            or len(content_container.xpath("./div")) != 1
        ):
            continue
        wrapper = content_container.xpath("./div")[0]
        wrapper_children = [
            child for child in wrapper if isinstance(child.tag, str)
        ]
        child_tags = [_tag(child) for child in wrapper_children]
        if child_tags == ["table", "p"]:
            service_notice = None
            table, disclaimer = wrapper_children
        elif child_tags == ["p", "table", "p"]:
            leading_notice, table, disclaimer = wrapper_children
            leading_text = plain_text(leading_notice)
            if leading_text in {
                _WILEY_SUPPORTING_SERVICE_NOTICE,
                _WILEY_SUPPORTING_ONLINE_NOTICE,
            }:
                service_notice = leading_notice
            elif leading_text == _WILEY_SUPPORTING_RETAINED_ONLINE_NOTICE:
                # This exact Biopolymers wording is printed in the article PDF
                # and is therefore authored front matter. Keep it while
                # removing only the adjacent download chrome and publisher
                # disclaimer under the otherwise complete Wiley signature.
                service_notice = None
            else:
                continue
        else:
            continue
        if plain_text(disclaimer) != _WILEY_SUPPORTING_DISCLAIMER:
            continue

        headers = table.xpath("./thead/tr/th")
        rows = table.xpath("./tbody/tr")
        if (
            len(headers) != 2
            or [plain_text(header) for header in headers]
            != ["Filename", "Description"]
            or [header.get("id") for header in headers]
            != ["article-filename", "article-description"]
            or [header.get("scope") for header in headers] != ["col", "col"]
            or not rows
        ):
            continue

        descriptions: list[tuple[Any, str]] = []
        valid = True
        for row in rows:
            cells = row.xpath("./td")
            if (
                len(cells) != 2
                or [cell.get("headers") for cell in cells]
                != ["article-filename", "article-description"]
            ):
                valid = False
                break
            links = cells[0].xpath("./a[@href]")
            if len(links) != 1 or any(
                isinstance(child.tag, str) and child is not links[0]
                for child in cells[0]
            ):
                valid = False
                break
            filename = plain_text(links[0])
            link_match = link_pattern.fullmatch((links[0].get("href") or "").strip())
            metadata = plain_text(cells[0]).removeprefix(filename)
            description = plain_text(cells[1])
            description_children = [
                child for child in cells[1] if isinstance(child.tag, str)
            ]
            paragraph_description = bool(description_children) and (
                all(_tag(child) == "p" for child in description_children)
                and not (cells[1].text or "").strip()
                and not any((child.tail or "").strip() for child in description_children)
                and all(plain_text(child) for child in description_children)
            )
            inline_tags = {"a", "b", "br", "em", "i", "span", "strong", "sub", "sup"}
            inline_description = (
                not paragraph_description
                and all(
                    _tag(descendant) in inline_tags
                    for child in description_children
                    for descendant in child.iter()
                    if isinstance(descendant.tag, str)
                )
            )
            if description_children and not (
                paragraph_description or inline_description
            ):
                valid = False
                break
            row_id = (row.get("id") or "").strip()
            if (
                link_match is None
                or doi_pattern.fullmatch(unquote(link_match.group("doi"))) is None
                or unquote_plus(link_match.group("file")) != filename
                or (
                    row_id
                    and not filename.startswith(f"{row_id}-")
                    and not filename.startswith(f"{row_id}.")
                    and re.fullmatch(
                        r"[a-z][a-z0-9]{2,31}-supitem-\d{4}",
                        row_id,
                        re.IGNORECASE,
                    )
                    is None
                )
                or metadata_pattern.fullmatch(metadata) is None
                or not description
            ):
                valid = False
                break
            if paragraph_description:
                descriptions.extend(
                    (copy.deepcopy(child), child.getroottree().getpath(child))
                    for child in description_children
                )
            else:
                paragraph = etree.Element("p")
                paragraph.text = cells[1].text
                for child in cells[1]:
                    paragraph.append(copy.deepcopy(child))
                descriptions.append(
                    (paragraph, cells[1].getroottree().getpath(cells[1]))
                )
        if valid:
            chrome = [table, disclaimer]
            if service_notice is not None:
                chrome.insert(0, service_notice)
            plans.append((wrapper, chrome, descriptions))

    for wrapper, chrome, descriptions in plans:
        position = min(wrapper.index(element) for element in chrome)
        for element in chrome:
            wrapper.remove(element)
        for offset, (paragraph, source_locator) in enumerate(descriptions):
            paragraph.set(
                _NORMALIZED_KIND_ATTRIBUTE, "wiley-supporting-description"
            )
            paragraph.set(_NORMALIZED_SOURCE_LOCATOR_ATTRIBUTE, source_locator)
            wrapper.insert(position + offset, paragraph)


def _remove_empty_wiley_citing_literature_service_section(document: Any) -> None:
    """Remove only Wiley's exact empty cited-by service container.

    ``Citing Literature`` is publisher interface chrome when its dedicated
    content container is empty.  Authored prose or populated cited-by entries
    are retained by requiring the complete empty service signature.
    """

    for section in document.xpath('//section[@id="cited-by"]'):
        variants = (
            (
                './div/h2/div[@role="button"]/span[@id="citedby-section"]',
                './div/div[@id="cited-by__content"]',
            ),
            (
                './div/div/h2/div[@role="button"]/span[@id="citedby-section"]',
                './div/div/div[@id="cited-by__content"]',
            ),
        )
        matches = [
            (section.xpath(heading_path), section.xpath(content_path))
            for heading_path, content_path in variants
        ]
        matches = [
            (headings, contents)
            for headings, contents in matches
            if len(headings) == 1 and len(contents) == 1
        ]
        if len(matches) != 1:
            continue
        headings, contents = matches[0]
        if (
            plain_text(headings[0]) != "Citing Literature"
            or plain_text(contents[0])
            or contents[0].xpath(".//img | .//table | .//figure | .//a[@href]")
            or plain_text(section) != "Citing Literature"
        ):
            continue
        parent = section.getparent()
        if parent is not None:
            parent.remove(section)


def _normalize_wiley_molar_unit_spans(document: Any) -> None:
    """Restore the capital molarity marker encoded as one lowercase span.

    Some Wiley article snapshots serialize the visually small-cap ``M`` in
    concentration units as an attribute-free ``<span>m</span>``.  The adjacent
    numeric value and optional SI prefix distinguish that publisher encoding
    from an ordinary italic variable or a literal metre unit, which is not
    wrapped this way.  Normalize the DOM before both plain-text and rich-text
    rendering so ``nM``, ``mM``, ``μM``, and standalone ``M`` agree.
    """

    numeric_unit_prefix = re.compile(
        r"(?:^|[^\d])\d+(?:[.,]\d+)?"
        r"(?:[\s\u00a0\u2000-\u200a]+|-)(?:[nmµμ])?$"
    )
    cell_press = _cell_press_header_details(document) is not None
    for unit in document.xpath("//span[not(@*) and not(*)]"):
        if normalize_space("".join(unit.itertext())) != "m":
            continue
        parent = unit.getparent()
        if parent is None:
            continue
        previous = unit.getprevious()
        before = previous.tail if previous is not None else parent.text
        after = unit.tail or ""
        if cell_press:
            # Semantic publisher archives retain small-cap molarity as an
            # attribute-free span, including inverse-M and table unit rows.
            exponent = unit.getnext()
            inverse = (previous is not None and _tag(previous) == 'sup'
                       and re.fullmatch(r'\d+', plain_text(previous))
                       and exponent is not None and _tag(exponent) == 'sup'
                       and plain_text(exponent) in {'−1', '-1'})
            unit_row = (bool(unit.xpath('ancestor::td'))
                        and _tag(parent) in {'i', 'em'}
                        and (parent.text or '').strip() in {'n', 'μ', 'm'}
                        and len(parent) == 1)
            joined = re.search(r'\d+(?:\.\d+)?\s*[pnmμ]?$', before or '')
            if inverse or unit_row or joined:
                unit.text = 'M'
                continue
        if not numeric_unit_prefix.search(before or "") or not re.match(
            r"^(?:\s|[,;:.)])", after
        ):
            continue
        unit.text = "M"


def _normalize_sciencedirect_supplement_attachment_paragraphs(document: Any) -> None:
    """Retain authored lead text while removing one exact download control.

    Current ScienceDirect supplementary-data paragraphs can place authored
    lead prose directly in ``div#p####`` and nest the human-readable attachment
    label below a download-only SVG/link control.  The generic body walker
    sees only the nested ``p`` and therefore loses the lead.  Collapse only the
    fully verified publisher structure to one ordinary paragraph; a partial
    or ambiguous card remains untouched.
    """

    lead_pattern = re.compile(
        r"The following is the Supplementary data to this article:",
        flags=re.IGNORECASE,
    )
    attachment_pattern = re.compile(r"mmc(?P<number>\d+)", re.IGNORECASE)
    label_pattern = re.compile(
        r"Multimedia component (?P<number>\d+)\.", re.IGNORECASE
    )

    for section in document.xpath("//section"):
        headings = section.xpath("./h2 | ./h3 | ./h4")
        if (
            len(headings) != 1
            or not plain_text(headings[0]).casefold().endswith("supplementary data")
        ):
            continue
        # The exact legacy EC card contains a download-only control beside
        # authored prose. Supplements are independently inventoried/linked.
        for anchor in list(section.xpath('.//span[starts-with(@id,"ec")]//a[@download and @href]')):
            if (re.fullmatch(r"https://ars\.els-cdn\.com/content/image/[^/]+-mmc\d+\.[A-Za-z0-9]+", anchor.get("href") or "")
                    and plain_text(anchor).startswith("Download:")
                    and (anchor.get("title") or "").startswith("Download ")):
                anchor.drop_tree()
        for container in section.xpath("./div[@id]"):
            if (
                re.fullmatch(
                    r"p[0-9a-f]+", container.get("id") or "", re.IGNORECASE
                )
                is None
                or lead_pattern.fullmatch(normalize_space(container.text or ""))
                is None
            ):
                continue
            direct_children = [
                child for child in container if isinstance(child.tag, str)
            ]
            if len(direct_children) != 1 or _tag(direct_children[0]) != "span":
                continue
            wrapper = direct_children[0]
            cards = [child for child in wrapper if isinstance(child.tag, str)]
            if not cards:
                continue

            labels: list[str] = []
            valid = True
            for expected_number, card in enumerate(cards, start=1):
                identifier = attachment_pattern.fullmatch(card.get("id") or "")
                anchors = card.xpath('.//a[@href and @download]')
                label_nodes = card.xpath(".//p")
                label = plain_text(label_nodes[0]) if len(label_nodes) == 1 else ""
                label_match = label_pattern.fullmatch(label)
                if (
                    _tag(card) != "span"
                    or identifier is None
                    or int(identifier.group("number")) != expected_number
                    or len(anchors) != 1
                    or len(label_nodes) != 1
                    or label_match is None
                    or int(label_match.group("number")) != expected_number
                    or not plain_text(anchors[0]).startswith("Download:")
                    or not normalize_space(anchors[0].get("title") or "").startswith(
                        "Download"
                    )
                    or plain_text(card) != f"{plain_text(anchors[0])}{label}"
                ):
                    valid = False
                    break
                labels.append(label)
            if not valid:
                continue

            lead = normalize_space(container.text or "")
            for child in list(container):
                container.remove(child)
            container.tag = "p"
            container.text = f"{lead} {' '.join(labels)}"


_PLOS_ARTICLE_DOI = re.compile(
    r"https://doi\.org/(10\.1371/journal\.[a-z0-9]+(?:\.[a-z0-9]+)+)/?",
    re.IGNORECASE,
)


def _flat_plos_figure_details(
    anchor: Any, article_doi: str, expected_number: int
) -> dict[str, Any] | None:
    """Return one exact archived PLOS figure card, if fully consistent."""

    suffix = f"g{expected_number:03d}"
    article_key = article_doi.removeprefix("10.1371/journal.").replace(".", "-")
    if (
        _tag(anchor) != "a"
        or (anchor.get("id") or "").casefold()
        != f"{article_key}-{suffix}".casefold()
        or plain_text(anchor)
    ):
        return None
    card = anchor.getnext()
    if card is None or _tag(card) != "div" or card.attrib:
        return None
    children = [child for child in card if isinstance(child.tag, str)]
    if [_tag(child) for child in children] != [
        "div",
        "div",
        "div",
        "p",
        "p",
        "p",
        "p",
    ]:
        return None
    images = children[0].xpath('.//img[@src and @alt]')
    if len(images) != 1:
        return None
    image = images[0]
    expected_figure_doi = f"{article_doi}.{suffix}"
    image_links = image.xpath("ancestor::a[1]")
    if (
        normalize_space(image.get("alt") or "") != f"Figure {expected_number}."
        or re.match(
            r"data:image/(?:png|tiff);base64,",
            image.get("src") or "",
            flags=re.IGNORECASE,
        )
        is None
        or len(image_links) != 1
        or (image_links[0].get("href") or "")
        != f"article/figure/image?size=medium&id={expected_figure_doi}"
    ):
        return None
    download_links = children[1].xpath(".//a[@href]")
    if (
        re.sub(r"\s+", "", plain_text(children[1])).casefold()
        != "download:pnglargerimagetifforiginalimage"
        or [re.sub(r"\s+", "", plain_text(link)).casefold() for link in download_links]
        != ["pnglargerimage", "tifforiginalimage"]
        or [link.get("href") for link in download_links]
        != [
            f"article/figure/image?download&size=large&id={expected_figure_doi}",
            f"article/figure/image?download&size=original&id={expected_figure_doi}",
        ]
    ):
        return None
    label = plain_text(children[2])
    label_match = re.match(
        r"^Fig(?:ure)?\.?\s*(\d+)\.", label, flags=re.IGNORECASE
    )
    if (
        label_match is None
        or int(label_match.group(1)) != expected_number
        or plain_text(children[3])
        or not plain_text(children[4])
        or plain_text(children[5])
    ):
        return None
    doi_links = children[6].xpath("./a[@href]")
    if (
        len(doi_links) != 1
        or plain_text(children[6]) != f"https://doi.org/{expected_figure_doi}"
        or (doi_links[0].get("href") or "")
        != f"https://doi.org/{expected_figure_doi}"
    ):
        return None
    return {
        "anchor": anchor,
        "card": card,
        "image": image,
        "label": children[2],
        "body": children[4],
    }


def _semantic_plos_figure_details(
    figure: Any, article_doi: str, expected_number: int
) -> dict[str, Any] | None:
    """Return one exact semantic PLOS figure card, if fully consistent."""

    if (
        _tag(figure) != "figure"
        or (figure.get("id") or "") != f"figure-{expected_number}"
    ):
        return None
    children = [child for child in figure if isinstance(child.tag, str)]
    child_tags = [_tag(child) for child in children]
    if child_tags not in (
        ["div", "div", "div", "p", "p", "p"],
        ["div", "div", "div", "p", "p", "p", "p"],
    ):
        return None
    images = children[0].xpath('.//img[@src and @alt]')
    if len(images) != 1:
        return None
    image = images[0]
    expected_figure_doi = f"{article_doi}.g{expected_number:03d}"
    image_links = image.xpath("ancestor::a[1]")
    image_alt = normalize_space(image.get("alt") or "").casefold()
    if (
        image_alt
        not in {"thumbnail", f"figure {expected_number}.".casefold()}
        or re.match(
            r"data:image/(?:png|tiff);base64,",
            image.get("src") or "",
            flags=re.IGNORECASE,
        )
        is None
        or len(image_links) != 1
        or (image_links[0].get("href") or "")
        != f"article/figure/image?size=medium&id={expected_figure_doi}"
    ):
        return None
    download_links = children[1].xpath(".//a[@href]")
    if (
        re.sub(r"\s+", "", plain_text(children[1])).casefold()
        != "download:pnglargerimagetifforiginalimage"
        or [re.sub(r"\s+", "", plain_text(link)).casefold() for link in download_links]
        != ["pnglargerimage", "tifforiginalimage"]
        or [link.get("href") for link in download_links]
        != [
            f"article/figure/image?download&size=large&id={expected_figure_doi}",
            f"article/figure/image?download&size=original&id={expected_figure_doi}",
        ]
    ):
        return None
    label = plain_text(children[2])
    label_match = re.match(
        r"^Fig(?:ure)?\.?\s*(\d+)\.", label, flags=re.IGNORECASE
    )
    if (
        label_match is None
        or int(label_match.group(1)) != expected_number
        or plain_text(children[3])
        or not plain_text(children[4])
        or (len(children) == 7 and plain_text(children[5]))
    ):
        return None
    doi_paragraph = children[-1]
    doi_links = doi_paragraph.xpath("./a[@href]")
    if (
        len(doi_links) != 1
        or plain_text(doi_paragraph) != f"https://doi.org/{expected_figure_doi}"
        or (doi_links[0].get("href") or "")
        != f"https://doi.org/{expected_figure_doi}"
    ):
        return None
    return {
        "figure": figure,
        "image": image,
        "label": children[2],
        "body": children[4],
    }


def _semantic_plos_table_details(
    figure: Any, article_doi: str, expected_number: int
) -> dict[str, Any] | None:
    """Return one exact semantic PLOS raster-table card, if consistent."""

    if (
        _tag(figure) != "figure"
        or (figure.get("id") or "") != f"table-{expected_number}"
    ):
        return None
    children = [child for child in figure if isinstance(child.tag, str)]
    if (
        len(children) < 5
        or [_tag(child) for child in children[:3]] != ["div", "div", "div"]
        or any(_tag(child) != "p" for child in children[3:])
    ):
        return None
    images = children[0].xpath('.//img[@src and @alt]')
    if len(images) != 1:
        return None
    image = images[0]
    expected_table_doi = f"{article_doi}.t{expected_number:03d}"
    image_links = image.xpath("ancestor::a[1]")
    if (
        normalize_space(image.get("alt") or "").casefold() != "thumbnail"
        or re.match(
            r"data:image/(?:png|tiff);base64,",
            image.get("src") or "",
            flags=re.IGNORECASE,
        )
        is None
        or len(image_links) != 1
        or (image_links[0].get("href") or "")
        != f"article/figure/image?size=medium&id={expected_table_doi}"
    ):
        return None
    download_links = children[1].xpath(".//a[@href]")
    if (
        re.sub(r"\s+", "", plain_text(children[1])).casefold()
        != "download:pnglargerimagetifforiginalimage"
        or [re.sub(r"\s+", "", plain_text(link)).casefold() for link in download_links]
        != ["pnglargerimage", "tifforiginalimage"]
        or [link.get("href") for link in download_links]
        != [
            f"article/figure/image?download&size=large&id={expected_table_doi}",
            f"article/figure/image?download&size=original&id={expected_table_doi}",
        ]
    ):
        return None
    labels = children[2].xpath("./span[1]")
    if (
        len(labels) != 1
        or re.fullmatch(
            rf"Table\s+{expected_number}\.\s*",
            plain_text(labels[0]),
            flags=re.IGNORECASE,
        )
        is None
        or not plain_text(children[2])
        or plain_text(children[3])
    ):
        return None
    doi_links = children[-1].xpath("./a[@href]")
    if (
        len(doi_links) != 1
        or plain_text(children[-1]) != f"https://doi.org/{expected_table_doi}"
        or (doi_links[0].get("href") or "")
        != f"https://doi.org/{expected_table_doi}"
    ):
        return None
    return {
        "figure": figure,
        "image": image,
        "title": children[2],
        "notes": [node for node in children[4:-1] if plain_text(node)],
        "number": expected_number,
    }


def _flat_plos_table_details(
    anchor: Any, article_doi: str, expected_number: int
) -> dict[str, Any] | None:
    """Return one exact archived PLOS raster-table card, if consistent."""

    suffix = f"t{expected_number:03d}"
    article_key = article_doi.removeprefix("10.1371/journal.").replace(".", "-")
    if (
        _tag(anchor) != "a"
        or (anchor.get("id") or "").casefold()
        != f"{article_key}-{suffix}".casefold()
        or plain_text(anchor)
    ):
        return None
    card = anchor.getnext()
    if card is None or _tag(card) != "div" or card.attrib:
        return None
    children = [child for child in card if isinstance(child.tag, str)]
    if (
        len(children) < 5
        or [_tag(child) for child in children[:3]] != ["div", "div", "div"]
        or any(_tag(child) != "p" for child in children[3:])
    ):
        return None
    images = children[0].xpath('.//img[@src and @alt]')
    if len(images) != 1:
        return None
    image = images[0]
    expected_table_doi = f"{article_doi}.{suffix}"
    image_links = image.xpath("ancestor::a[1]")
    if (
        normalize_space(image.get("alt") or "").casefold() != "thumbnail"
        or re.match(
            r"data:image/(?:png|tiff);base64,",
            image.get("src") or "",
            flags=re.IGNORECASE,
        )
        is None
        or len(image_links) != 1
        or (image_links[0].get("href") or "")
        != f"article/figure/image?size=medium&id={expected_table_doi}"
    ):
        return None
    download_links = children[1].xpath(".//a[@href]")
    if (
        re.sub(r"\s+", "", plain_text(children[1])).casefold()
        != "download:pnglargerimagetifforiginalimage"
        or [re.sub(r"\s+", "", plain_text(link)).casefold() for link in download_links]
        != ["pnglargerimage", "tifforiginalimage"]
        or [link.get("href") for link in download_links]
        != [
            f"article/figure/image?download&size=large&id={expected_table_doi}",
            f"article/figure/image?download&size=original&id={expected_table_doi}",
        ]
    ):
        return None
    labels = children[2].xpath("./span[1]")
    if (
        len(labels) != 1
        or re.fullmatch(
            rf"Table\s+{expected_number}\.\s*",
            plain_text(labels[0]),
            flags=re.IGNORECASE,
        )
        is None
        or not plain_text(children[2])
        or plain_text(children[3])
    ):
        return None
